<?php defined('BASEPATH') or exit('No direct script access allowed'); ?>
<h3>Consulta pontual de cobranças no Asaas</h3>
<p>Esta consulta usa a conta e o ambiente indicados. O resultado remoto não registra recebimento, não associa cobrança sem vínculo e não substitui a conferência da fatura.</p>
<?php foreach($accounts as $remoteAccount){if(!(int)$remoteAccount['enabled']||$remoteAccount['verified_at']===null)continue;$remoteId=(int)$remoteAccount['id']; ?>
<article class="panel panel-default" data-remote-monitor-account="<?= $remoteId; ?>"><div class="panel-body"><h4><?= $e($remoteAccount['account_id'].' · '.$environmentLabel($remoteAccount['environment'])); ?></h4>
<form method="post" action="<?= $e($action_url); ?>#monitor">
<?php $hidden(['action'=>'remote_monitor','account_row'=>$remoteId,'account_revision'=>$remoteAccount['revision'],'company_asaas_preferences_csrf'=>$preferences_csrf]); ?>
<div class="row"><div class="col-md-6 form-group"><label for="remote-state-<?= $remoteId; ?>">Situação no Asaas</label><select class="form-control" id="remote-state-<?= $remoteId; ?>" name="remote_filters[status]"><?php foreach(['all'=>'Todas','PENDING'=>'Pendente','OVERDUE'=>'Vencida','CONFIRMED'=>'Confirmada','RECEIVED'=>'Recebida','RECEIVED_IN_CASH'=>'Recebida em dinheiro'] as $key=>$label){ ?><option value="<?= $e($key); ?>"><?= $e($label); ?></option><?php } ?></select></div>
<div class="col-md-6 form-group"><label for="remote-date-<?= $remoteId; ?>">Filtrar por data de</label><select class="form-control" id="remote-date-<?= $remoteId; ?>" name="remote_filters[date_field]"><option value="payment">Pagamento</option><option value="due">Vencimento</option><option value="created">Criação</option></select></div>
<div class="col-md-6 form-group"><label for="remote-from-<?= $remoteId; ?>">Desde</label><input class="form-control" id="remote-from-<?= $remoteId; ?>" type="date" name="remote_filters[date_from]"></div><div class="col-md-6 form-group"><label for="remote-to-<?= $remoteId; ?>">Até</label><input class="form-control" id="remote-to-<?= $remoteId; ?>" type="date" name="remote_filters[date_to]"></div></div>
<button class="btn btn-default" type="submit">Consultar esta conta no Asaas</button></form>
<?php if(($remote_monitor['account_row']??null)===$remoteId){$remotePage=$remote_monitor['page']; ?>
<div class="table-responsive"><table class="table"><thead><tr><th>Cobrança</th><th>Situação consultada</th><th>Meio</th><th>Valor remoto</th><th>Vínculo existente</th></tr></thead><tbody>
<?php foreach($remotePage['items'] as $item){ ?><tr><td><?= $e($item['remote_id']); ?></td><td><?= $e($item['status']); ?></td><td><?= $e($item['billing_type']); ?></td><td><?= $e($item['value']); ?></td><td><?= $item['origin_id']===null?'Sem vínculo comprovado':$e('Origem #'.$item['origin_id'].' · Fatura #'.$item['invoice_id']); ?></td></tr><?php }if(!$remotePage['items']){ ?><tr><td colspan="5">Nenhuma cobrança nesta página.</td></tr><?php } ?></tbody></table></div>
<?php if($remotePage['next_offset']!==null){ ?><form method="post" action="<?= $e($action_url); ?>#monitor"><?php $hidden(['action'=>'remote_monitor','account_row'=>$remoteId,'account_revision'=>$remote_monitor['account_revision'],'company_asaas_preferences_csrf'=>$preferences_csrf]);foreach(array_replace($remote_monitor['filters'],['offset'=>$remotePage['next_offset']]) as $key=>$value){ ?><input type="hidden" name="remote_filters[<?= $e($key); ?>]" value="<?= $e($value); ?>"><?php } ?><button class="btn btn-default" type="submit">Consultar próxima página no Asaas</button></form><?php } ?>
<?php } ?></div></article><?php } ?>
